import {esc,badge,intro,empty,stat} from '../presentation.mjs';
export function instructorsView({state}){return `${intro('Instructor approvals','Review each instructor before they accept learners.')}<button class="primary" id="add-instructor">Assign instructor by email</button><section class="panel panel-pad">${state.instructors.map(i=>`<div class="syllabus-item"><div><b>${esc(i.name)}</b><p>${esc(i.phone)} · ${esc(i.specialty)}</p>${badge(i.approval_status)}</div><div>${i.approval_status!=='approved'?`<button class="primary" data-instructor="${esc(i.id)}" data-status="approved">Approve</button>`:''}${i.approval_status!=='rejected'?`<button class="danger" data-instructor="${esc(i.id)}" data-status="rejected">Reject</button>`:''}</div></div>`).join('')||empty('No instructor applications yet')}</section>`;}
export function fleetView({state}){return `${intro('Training fleet','Only active vehicles are offered for booking.')}<button class="primary" id="add-vehicle">Add vehicle</button><section class="panel panel-pad section-gap">${state.vehicles.map(v=>`<div class="syllabus-item"><div><b>${esc(v.name)}</b><p>${esc(v.reg)} · ${esc(v.transmission)}</p>${badge(v.active?'active':'inactive')}</div><button class="secondary" data-vehicle="${esc(v.id)}" data-active="${!v.active}">${v.active?'Deactivate':'Activate'}</button></div>`).join('')||empty('No vehicles yet')}</section>`;}

export function adminOverview({metrics}) { return `${intro('School overview','Manage the people and resources behind every lesson.')}<div class="stats">${stat('Learners',metrics.total_learners||0)}${stat('Pending instructors',metrics.pending_instructors||0)}${stat('Active plans',metrics.active_enrollments||0)}${stat('Receipts to review',metrics.review_payments||0)}</div><section class="panel panel-pad section-gap"><h2>School operations</h2><p class="sub">Review instructor applications, add real training vehicles, and reconcile payments before learners book.</p><div class="grid-buttons section-gap"><button class="secondary" data-nav="instructors">Review instructors</button><button class="secondary" data-nav="fleet">Manage fleet</button><button class="secondary" data-nav="payments">Review payments</button></div></section>`; }
